    ...leftOut.map((draft) => renderDraft(draft, drafts.indexOf(draft))),
    state.reviewError &&
      el("p", { class: "error-text", role: "alert" }, state.reviewError),
    el(
      "div",
      { class: "actions" },
      save,
      button("Cancel", () => {
        state.drafts = null;
        state.reviewError = null;
        render();
      }),
    ),
  );
}

